import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const path = file => fileURLToPath(new URL(file,import.meta.url));
const marker='_M0FP210JingLan0v03stn25first__resource__conflict';
const variant=process.argv[2];
const outputs=[];
for(const driver of ['deepbench','lookupbench']){
 let src=readFileSync(path(variant+'-'+driver+'.js'),'utf8');
 const wrap=name=>`const saved_${name} = ${name};
 ${name} = (...args) => {
  const start = performance.now(); stats.calls[${JSON.stringify(name)}]++;
  try { return saved_${name}(...args); }
  finally { stats.ms[${JSON.stringify(name)}] += performance.now() - start; }
 };`;
 const funcs=[marker];
 for(const name of ['_M0FP210JingLan0v03stn21same__resource__pairs','_M0FP210JingLan0v03stn21next__resource__tasks', '_M0FP210JingLan0v03stn23first__linked__conflict']){
  if(src.includes('function '+name+'(')) funcs.push(name);
 }
 for(const name of funcs){
  const begin=src.indexOf('function '+name+'(');
  const end=src.indexOf('\nfunction ',begin+1);
  assert(begin>=0 && end>begin);
  const prev=src.slice(begin,end);
  const resource=/_M0IPC16option6OptionPB2Eq5equalGsE\([^\n]*?\.resource, _resource\)/g;
  const next=prev.replace(resource,'(++stats.resourceChecks, $&)').replace(/if \((.*BigInt\.asIntN.*)\) \{/g,
    (_,cond)=>'if ('+(cond.includes('stats.resourceChecks')?cond.replace('(BigInt','(++stats.overlapTests, BigInt'):'(++stats.overlapTests, '+cond+')')+') {');
  assert.notEqual(prev,next);
  src=src.slice(0,begin)+next+src.slice(end);
 }
 const init=JSON.stringify(Object.fromEntries(funcs.map(n=>[n,0])));
 const header=`const stats={resourceChecks:0,overlapTests:0,calls:${init},ms:${init}};
${funcs.map(wrap).join('\n')}
process.once('exit',()=>console.error(JSON.stringify(stats)));\n`;
 writeFileSync(path(variant+'-'+driver+'-probe.js'),header+src);
}
for(const name of ['tight-impossible','maintenance','independent','distinct-resources','first-pair','last-pair','four-resources','one-resource','max-model']){
 const args=name==='tight-impossible'?[path(variant+'-deepbench-probe.js')]:[path(variant+'-lookupbench-probe.js'),name];
 const samples=Array.from({length:3},()=>{
  const p=spawnSync(process.execPath,args,{encoding:'utf8',timeout:40000});
  assert.equal(p.status,0,p.stderr);
  assert.equal(p.stdout.trim().split(/\r?\n/).length,9);
  return JSON.parse(p.stderr);
 });
 outputs.push({name,samples});
}
writeFileSync(path(variant+'-probe.json'),JSON.stringify(outputs,null,2)+'\n');
for(const r of outputs) console.log(r.name,JSON.stringify(r.samples[0]));

